        policy: "psychic",
        inspectionPolicy: "awa_repeat_optional_v1",
        lastTarget: null,
        lastDay: null,
        history: [],
      },
      source: { kind: "gift", actorId: 1 },
      startsOnDay: 1,
      maxUses: null,
    },
    events,
  );
  (
    gift.state.history as {
      day: number;
      targetId: import("@ai-werewolf-arena/game-contract").EntityId;
      result: Extract<
        import("@ai-werewolf-arena/game-contract").InspectionResult,
